126	                package_manifest_decls.insert(primary_id.clone(), (rel_path.clone(), decls))
127	            {
128	                return Err(GraphError::DuplicatePackage {
129	                    id: primary_id,
130	                    paths: vec![existing_path, rel_path],
131	                });
132	            }
133	        }
134	
135	        let mut packages = BTreeMap::new();
136	        for (id, (rel_path, decls)) in package_manifest_decls {
