  "criterion": "In a workspace with two or more napi/maturin/runtime-version-bearing packages, running `callisto matrix --package <name> --format json` where <name> is exactly one package's PackageId::name() string produces a report containing only that package's entries in platformTargets and runtimeVersions (all other packages' keys absent from both maps). --package matches against the same PackageId::name() string used as the map keys (see api_surface's package identity note) -- not display_name() and not a partial/glob match.",
  "is_error_case": false
},
{
  "id": "AC-007",
  "criterion": "Running `callisto matrix --package does-not-exist --format json` in any workspace exits with code 1 and prints a human-readable error message that names \"does-not-exist\" as an unrecognised package (no PackageId::name() in the workspace's registered package set matches it); it does not print a structurally valid empty MatrixReport.",
  "is_error_case": true
},

